function validate([n, edges, source, destination]) {
  if (!Number.isInteger(n) || n < 1 || n > 10000) return 'n is between 1 and 10^4.';
  if (!Array.isArray(edges) || edges.length > 10000) return 'edges has at most 10^4 pairs.';
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [a, b].';
    if (edge.some(v => !Number.isInteger(v) || v < 0 || v >= n)) return 'Edge endpoints are between 0 and n - 1.';
  }
  if (!Number.isInteger(source) || source < 0 || source >= n) return 'source is between 0 and n - 1.';
  if (!Number.isInteger(destination) || destination < 0 || destination >= n) return 'destination is between 0 and n - 1.';
  return null;
}

