function leadsToDestination(n, edges, source, destination) {
  const reach = new Set([source]);
  let grew = true;
  while (grew) {
    grew = false;
    for (const [a, b] of edges) if (reach.has(a) && !reach.has(b)) { reach.add(b); grew = true; }
  }
  for (const v of reach) if (v !== destination && !edges.some(([a]) => a === v)) return false;
  // Peel off reachable nodes whose edges all lead to already peeled nodes; a cycle never peels.
  const alive = new Set(reach);
  let peeled = true;
  while (peeled) {
    peeled = false;
    for (const v of [...alive]) if (!edges.some(([a, b]) => a === v && alive.has(b))) { alive.delete(v); peeled = true; }
  }
  if (alive.size > 0) return false;
  return reach.has(destination) && !edges.some(([a]) => a === destination);
}

