function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 1200 + pick(600) : 1 + pick(6);
  // Order the nodes randomly; the last one is the destination and every other node gets an edge to a later node.
  const order = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = pick(i + 1); [order[i], order[j]] = [order[j], order[i]]; }
  const destination = order[n - 1];
  const edges = [];
  for (let i = 0; i < n - 1; i++) {
    const reachAhead = size === 'large' ? 1 + pick(Math.min(40, n - 1 - i)) : 1 + pick(n - 1 - i);
    edges.push([order[i], order[i + reachAhead]]);
  }
  const extra = n === 1 ? 0 : size === 'large' ? pick(2000 - edges.length) : pick(4);
  for (let e = 0; e < extra; e++) {
    const i = pick(n - 1), j = i + 1 + pick(n - 1 - i);
    edges.push([order[i], order[j]]);
  }
  // Break the guarantee some of the time: a back edge, a self-loop, a removed edge or an edge out of the destination.
  const mode = pick(size === 'large' ? 5 : 6);
  if (mode === 1 && n > 1) { const j = pick(n - 1), i = j + pick(n - j); edges.push([order[i], order[j]]); }
  else if (mode === 2) { const v = order[pick(n)]; edges.push([v, v]); }
  else if (mode === 3 && edges.length) edges.splice(pick(edges.length), 1);
  else if (mode === 4) edges.push([destination, order[pick(n)]]);
  for (let i = edges.length - 1; i > 0; i--) { const j = pick(i + 1); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  const source = rand() < 0.6 ? order[0] : order[pick(n)];
  return [n, edges, source, destination];
}
